from 写入第二遍 import add

add('01_001',2.5,'16:9，倾斜双人中景，从武士腰前侧斜看；武士在画面左下，青从右上横身切近。镜头随两人横移半个身位，经过青收拳咬牙、武士双手在腰前的构图。','青已经腾空，屈起的拳头贴近脸侧，咬紧牙继续逼近武士；她的长马尾向身后拉直，卷束甩过肩侧。武士压肩转向她，双手留在腰前，外衣被迎面风掀开；两人的距离继续缩短。','灰白天空铺底，少量深色碎屑掠过。','两人上方开阔天空给冷白柔光；外衣下部较暗。','衣摆裂风与低沉破空声，碎屑轻擦，近处短促吸气。',phase='middle',node={'青.阶段':'腾空逼近','武士.阶段':'转身应对'},pcard={'opening':'青带着明确攻击意图近身，武士仍控制腰前防备。','beats':['咬牙收拳、横身逼近','武士压肩转向来拳，衣摆外翻'],'coupling':'两人的防备与逼近在同一空间同时推进。','landing':'尚未接触，距离已缩短。'})
add('08_003',5,'16:9，街屋间固定远景，砖屋三角顶与圆窗夹在画面左侧，较高建筑立面框住右侧；越过低屋顶看树冠上方。','远处两团冲击尘浪先后翻起，较近的灰尘越过矮屋顶边缘，屋檐上的细灰抖落；第二团尘浪扩展时，画外惊叫与逃跑喊声接上，尘缘随后摊薄。','灰米砖屋、蓝灰屋面、深褐窗框；远处灰绿树冠与铅蓝云层，米灰烟尘向树冠上方展开。','开阔天空冷白漫射，建筑夹缝内较暗；尘浪不自行发光。','远处两次轰响有先后，瓦面碎屑滑响；呼救之后急促脚步从画外逼近。',japanese=['きゃあああ！','あああああ！みんな逃げろ！！'],tone='第一声尖叫；第二声惊慌高喊，句中换气。',phase='result',kind='mixed',node={'场景焦点':'城内破坏与撤离'},meaning='从空中交手转入城内受波及范围；原作中间另有支线，时间已推进。')
add('09_001',1.5,'16:9，离地低机位倾斜跟拍奔跑鞋底，画面中心是一条深色裤腿，左缘只露另一人的鞋尖与衣摆；相机跟随一跨步后让鞋底掠出近侧。','深色鞋跟在石缝旁压下，前掌接着蹬开，另一只脚已经向前摆出；左侧同伴的鞋尖错半拍落地，衣摆擦过画面边缘，脚步不停。','近处灰米规整石砖迅速向后退，砖缝深灰、细尘被鞋底擦开；远处背景被腿部裁去。','上方天空经街巷敞口给柔和冷白光，脚下接触影短而软。','一重一轻的连续踏地声，衣摆擦响，远处呼喊延续后退。',phase='process',node={'撤离队.阶段':'持续奔跑'},meaning='脚步与下一格背人奔跑相接；具体脚的身份不在此格强认。')
